// Aggregate argus_llm_metrics per (hardware, model, quant, source).
// Per-request speed: generation_s, ttft_s, tokens_per_s (from LM Studio stats).
// Throughput: per execution, completion tokens / wall time of the LLM step.
const rows = $input.all().map(i => i.json).filter(r => r.model);
const num = (v) => (typeof v === 'number' && isFinite(v) ? v : null);
const stats = (arr) => {
  const v = arr.map(num).filter(x => x !== null).sort((a, b) => a - b);
  if (!v.length) return null;
  const q = (p) => v[Math.min(v.length - 1, Math.floor(p * v.length))];
  const mean = v.reduce((a, b) => a + b, 0) / v.length;
  const r = (x) => Math.round(x * 100) / 100;
  return { n: v.length, mean: r(mean), p50: r(q(0.5)), p95: r(q(0.95)), min: r(v[0]), max: r(v[v.length - 1]) };
};

const groups = {};
for (const r of rows) {
  const src = String(r.source || '').startsWith('benchmark') ? r.source : r.source || 'unknown';
  const key = [r.hardware, r.model, r.quant, src].join(' | ');
  (groups[key] = groups[key] || []).push(r);
}

const out = [];
for (const [key, g] of Object.entries(groups)) {
  const byExec = {};
  for (const r of g) (byExec[r.execution_id] = byExec[r.execution_id] || []).push(r);
  const throughput = Object.values(byExec).map(e => {
    const wall = Math.max(...e.map(r => num(r.llm_latency_s) || 0));
    const tok = e.reduce((a, r) => a + (num(r.completion_tokens) || 0), 0);
    return { concurrency: e.length, wall_s: wall, agg_tokens_per_s: wall ? Math.round(tok / wall * 10) / 10 : null,
             alerts_per_hour: wall ? Math.round(e.length / wall * 3600) : null };
  });
  const verdicts = {};
  for (const r of g) verdicts[r.verdict || 'none'] = (verdicts[r.verdict || 'none'] || 0) + 1;
  const ok = g.filter(r => r.success).length;
  out.push({ json: {
    group: key,
    hardware: g[0].hardware, model: g[0].model, quant: g[0].quant, arch: g[0].model_arch,
    context_length: g[0].context_length, source: g[0].source,
    runs: g.length,
    success_rate: Math.round(ok / g.length * 100) / 100,
    sections_ok_rate: Math.round(g.filter(r => r.sections_ok).length / g.length * 100) / 100,
    verdicts,
    injection_cases: g.filter(r => r.injection_suspected).map(r => ({ case: r.bench_case, verdict: r.verdict })),
    generation_s: stats(g.map(r => r.generation_s)),
    ttft_s: stats(g.map(r => r.ttft_s)),
    tokens_per_s_per_stream: stats(g.map(r => r.tokens_per_s)),
    prompt_tokens: stats(g.map(r => r.prompt_tokens)),
    completion_tokens: stats(g.map(r => r.completion_tokens)),
    reasoning_tokens: stats(g.map(r => r.reasoning_tokens)),
    pipeline_latency_s: stats(g.map(r => r.pipeline_latency_s)),
    throughput_by_execution: throughput,
  } });
}
return out.length ? out : [{ json: { note: 'no metrics yet' } }];
